#!/bin/bash
# User-space gem5 build environment (extracted RPMs, no root).
# Source this:  source ~/gem5-deps/env.sh
DEPS="$HOME/gem5-deps"
export PATH="$DEPS/usr/bin:$DEPS/py/usr/bin:$PATH"
export PYTHONPATH=$(find "$DEPS/usr" "$DEPS/py" -type d -name site-packages 2>/dev/null | tr '\n' ':')${PYTHONPATH:+:$PYTHONPATH}
export LD_LIBRARY_PATH=$(find "$DEPS" -type d \( -name lib64 -o -name lib \) -path '*/usr/*' 2>/dev/null | tr '\n' ':')${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}
export PKG_CONFIG_PATH=$(find "$DEPS" -name pkgconfig -type d 2>/dev/null | tr '\n' ':')${PKG_CONFIG_PATH:+:$PKG_CONFIG_PATH}

