99	    const char*
100	    CHAOSLSQFwd::structuralFaultToString(StructuralFault f) {
101	        switch (f) {
102	            case StructuralFault::ByteLaneSkew: return "byte_lane_skew";
103	            case StructuralFault::AllZero:      return "all_zero";
104	            case StructuralFault::None:         return "none";
