106	        return "none";
107	    }
108	
109	    // P-D1: apply a *structural* (whole-word) fault to the delivered data.
110	    // Unlike the bit-level FaultType path (one-byte AND/OR/XOR), these re-route
111	    // the entire delivered word:
112	    //   ByteLaneSkew: rotate the byte array right by k bytes — models the D1
113	    //     signature where core 179 delivered rol_k(stale array-head content)
114	    //     (15:58: rol1; 0814: rol6). A right-rotation by k delivers, for byte
115	    //     lane n, the content of lane (n+k) mod size — i.e. a fill-buffer
116	    //     byte-lane mux selecting the wrong phase. Verified bit-exact against
117	    //     the crash values (MICROARCH_SUPPLEMENT §2.2).
118	    //   AllZero: deliver an all-zero word — models the D1 "empty/invalid slot"
119	    //     state (15:42: __per_cpu_offset[176] delivered 0).
120	    // size is the forwarded size in bytes (typically 8 for a 64-bit GPR load).
121	    void
122	    CHAOSLSQFwd::applyStructuralFault(uint8_t *data, unsigned size, Addr vaddr)
123	    {
124	        if (size == 0) return;
125	        switch (structural_fault_enum) {
126	            case StructuralFault::ByteLaneSkew: {
127	                int k = skew_bytes;
128	                if (k == 0) {
129	                    std::uniform_int_distribution<int> kd(1, 7);
130	                    k = kd(rng);
